99:export function enableAPIEvents(enabled: boolean): void {
100:  if (!enabled) {
101:    apiEventSource?.close();
102:    apiEventSource = null;
103:    activityRevision.set(0);
104:    inFlightRequests.set(0);
105:    inflightRequestEntries.set([]);
106:    uiConfig.set(defaultUIConfig());
107:    profiles.set([]);
108:    activeProfile.set(null);
109:    profileRevision++;
110:    return;
111:  }
112:
113:  let retryCount = 0;
114:  const initialDelay = 1000; // 1 second
115:
116:  const connect = () => {
117:    apiEventSource?.close();
118:    apiEventSource = new EventSource("/api/events");
119:
120:    connectionState.set("connecting");
121:
122:    apiEventSource.onopen = () => {
123:      // Clear everything on connect to keep things in sync
124:      proxyLogs.set("");
125:      upstreamLogs.set("");
126:      activityRevision.update((n) => n + 1);
127:      inFlightRequests.set(0);
128:      inflightRequestEntries.set([]);
129:      uiConfig.set(defaultUIConfig());
130:      models.set([]);
131:      profiles.set([]);
132:      activeProfile.set(null);
133:      profileRevision++;
134:      retryCount = 0;
135:      connectionState.set("connected");
136:      void fetchProfiles().catch((error) => console.error(error));
137:    };
138:
139:    apiEventSource.onmessage = (e: MessageEvent) => {
140:      try {
141:        handleAPIEventMessage(e.data);
142:      } catch (err) {
143:        console.error(e.data, err);
144:      }
145:    };
146:
147:    apiEventSource.onerror = () => {
148:      apiEventSource?.close();
149:      retryCount++;
150:      const delay = Math.min(initialDelay * Math.pow(2, retryCount - 1), 5000);
151:      connectionState.set("disconnected");
152:      setTimeout(connect, delay);
153:    };
154:  };
155:
156:  connect();
157:}
