159:export function handleAPIEventMessage(data: string): void {
160:  const message = JSON.parse(data) as APIEventEnvelope;
161:  switch (message.type) {
162:    case "modelStatus": {
163:      const newModels = JSON.parse(message.data) as Model[];
164:      // Sort models by name and id
165:      newModels.sort((a, b) => {
166:        return (a.name + a.id).localeCompare(b.name + b.id, undefined, { numeric: true });
167:      });
168:      models.set(newModels);
169:      break;
170:    }
171:
172:    case "logData": {
173:      const logData = JSON.parse(message.data) as LogData;
174:      switch (logData.source) {
175:        case "proxy":
176:          appendLog(logData.data, proxyLogs);
177:          break;
178:        case "upstream":
179:          appendLog(logData.data, upstreamLogs);
180:          break;
181:      }
182:      break;
183:    }
184:
185:    case "activity": {
186:      activityRevision.update((n) => n + 1);
187:      break;
188:    }
189:
190:    case "inflight": {
191:      const stats = JSON.parse(message.data) as InFlightStats;
192:      const withReceiptTime = (request: InflightRequestEntry): InflightRequestEntry => ({
193:        ...request,
194:        client_received_at_ms: performance.now(),
195:      });
196:      inflightRequestEntries.update((current) => {
197:        let requests = current;
198:        switch (stats.operation) {
199:          case "snapshot":
200:            requests = (stats.requests ?? []).map(withReceiptTime);
201:            break;
202:          case "upsert": {
203:            if (!stats.request) break;
204:            const received = withReceiptTime(stats.request);
205:            const index = current.findIndex((request) => request.id === received.id);
206:            requests = index === -1
207:              ? [...current, received]
208:              : current.map((request, i) => i === index ? received : request);
209:            break;
210:          }
211:          case "remove":
212:            requests = current.filter((request) => request.id !== stats.id);
213:            break;
214:        }
215:        requests.sort((a, b) => {
216:          const byTime = Date.parse(a.timestamp) - Date.parse(b.timestamp);
217:          return byTime || a.id.localeCompare(b.id, undefined, { numeric: true });
218:        });
219:        inFlightRequests.set(requests.length);
220:        return requests;
221:      });
222:      break;
223:    }
224:
225:    case "uiConfig": {
226:      uiConfig.set(JSON.parse(message.data) as UIConfig);
227:      break;
228:    }
229:
230:    case "profileChanged": {
231:      const state = JSON.parse(message.data) as Pick<ProfileState, "active">;
232:      profileRevision++;
233:      activeProfile.set(state.active);
234:      break;
235:    }
236:  }
237:}
